\begin{table}[htbp]\centering\small
\caption{Primary first-pass reference-label accuracy (percent). Each cell uses 10,000 assigned valid calls. Parentheses are descriptive 95\% text-cluster bootstrap intervals. Mini denotes GPT-5.4-mini.}\label{tab:accuracy}
\begin{tabularx}{\linewidth}{lXX}\toprule
Condition & GPT-5.4 & Mini \\\midrule
A & 88.58 (87.95 to 89.20) & 84.90 (84.19 to 85.60) \\
B & 96.17 (95.77 to 96.53) & 95.45 (95.04 to 95.86) \\
C & 96.22 (95.83 to 96.61) & 95.70 (95.30 to 96.07) \\
\bottomrule
\end{tabularx}
\end{table}

\begin{table}[htbp]\centering\small
\caption{Controlled input conditions. All calls request a single Supported or Refuted label; evidence is supplied directly, with no retrieval.}\label{tab:conditions}
\begin{tabularx}{\linewidth}{lllX}\toprule
Condition & Claim & Selected evidence & First-sentence instruction \\\midrule
A & Present & Absent & Classify the claim as Supported or Refuted. \\
B & Present & Present & Same as A. \\
C & Present & Present & As B, with ``based only on the evidence provided'' added. \\
\bottomrule
\end{tabularx}
\end{table}

\begin{table}[htbp]\centering\small
\caption{Excess between-condition loss over the identical-left-prompt directional baseline, in percentage points. All three matched repetitions are reduced within claim. Parentheses are descriptive 95\% cluster intervals; the quantity is not permanent-error prevalence.}\label{tab:excess}
\begin{tabularx}{\linewidth}{lXX}\toprule
Contrast & GPT-5.4 & Mini \\\midrule
AB & 0.670 (0.481 to 0.871) & 0.253 (0.019 to 0.490) \\
BC & 0.387 (0.267 to 0.508) & 0.310 (0.183 to 0.440) \\
\bottomrule
\end{tabularx}
\end{table}
